#!/bin/bash
# Generated by scripts/export-killercoda.ts. Passes (exit 0) when the named checks of lab-m02-fix-the-yaml pass.
# Environment overrides, for local tests: SHELF_BIN, KUBECONFIG, SHELF_MARKER_DIR, SHELF_COURSE_DIR, SHELF_LABS_DIR.
LAB=lab-m02-fix-the-yaml
CHECKS="config-keys web-container-port web-service-port api-port-env worker-objects"
MARK="${SHELF_MARKER_DIR:-/tmp}"
SHELF="${SHELF_BIN:-/usr/local/bin/shelf}"
[ -f "$MARK/shelf-failed" ] && { echo "Setup failed: $(cat "$MARK/shelf-failed"). See /tmp/shelf-setup.log." >&2; exit 1; }
[ -f "$MARK/shelf-ready" ] || { echo "Setup is not finished. Wait for RESULT: ready in the first terminal, then click Check again." >&2; exit 1; }
export KUBECONFIG="${KUBECONFIG:-/root/.kube/config}"
cd "${SHELF_COURSE_DIR:-/root/course}" || { echo "The course folder is missing." >&2; exit 1; }
kubectl --context kind-reconcile --request-timeout=10s get nodes >/dev/null 2>&1 || { echo "The cluster is not reachable. Create it first (shelf up), and wait for the node to be Ready." >&2; exit 1; }
# Only this step's checks run, and each wait is capped at 30 s: the lab's own checks.yaml is replaced in a temporary copy of the labs folder.
LABS="${SHELF_LABS_DIR:-${SHELF_COURSE_DIR:-/root/course}/labs}"
T=$(mktemp -d) || { echo "Cannot make a temporary folder." >&2; exit 1; }
trap '[ -n "$T" ] && rm -rf "$T"' EXIT
for e in "$LABS"/*; do n=${e##*/}; [ "$n" = "$LAB" ] || ln -s "$e" "$T/$n"; done
cp -R "$LABS/$LAB" "$T/$LAB"
cat > "$T/$LAB/checks.yaml" <<'KILLERCODA_CHECKS'
apiVersion: labs.reconcile.example/v1
kind: LabChecks
lab: lab-m02-fix-the-yaml
checks:
  - id: config-keys
    describe: ConfigMap shelf-config has the keys mode and log-level
    kubectl:
      - get
      - configmap
      - shelf-config
      - -n
      - shelf
      - -o
      - jsonpath={.data.mode}/{.data.log-level}
    expect:
      equals: demo/info
    hint: Fix the tab in shelf-config.yaml, then run `kubectl apply --filename fix-the-yaml`.
  - id: web-container-port
    describe: Pod shelf-web declares the container port 8080 inside its container
    kubectl:
      - get
      - pod
      - shelf-web
      - -n
      - shelf
      - -o
      - jsonpath={.spec.containers[0].ports[0].containerPort}
    expect:
      equals: "8080"
    hint: In shelf-web-pod.yaml, the ports list belongs to the container, so it is indented under name and image.
  - id: web-service-port
    describe: Service shelf-web listens on the number 80
    kubectl:
      - get
      - service
      - shelf-web
      - -n
      - shelf
      - -o
      - jsonpath={.spec.ports[0].port}
    expect:
      equals: "80"
    hint: A Service port is a number. Remove the quotation marks around 80 in shelf-web-service.yaml.
  - id: api-port-env
    describe: Pod shelf-api has the environment variable SHELF_PORT with the text 8081
    kubectl:
      - get
      - pod
      - shelf-api
      - -n
      - shelf
      - -o
      - jsonpath={.spec.containers[0].env[?(@.name=="SHELF_PORT")].value}
    expect:
      equals: "8081"
    hint: An environment variable value is always a string. Put quotation marks around 8081 in shelf-api-pod.yaml.
  - id: worker-objects
    describe: ConfigMap shelf-worker-config and ServiceAccount shelf-worker both exist
    kubectl:
      - get
      - configmap/shelf-worker-config
      - serviceaccount/shelf-worker
      - -n
      - shelf
      - -o
      - name
    expect:
      regexCountAtLeast:
        pattern: ^(configmap/shelf-worker-config|serviceaccount/shelf-worker)$
        count: 2
    hint: Fix shelf-worker.yaml, then run `kubectl apply --filename fix-the-yaml` and look for errors.
KILLERCODA_CHECKS
out=$(SHELF_LABS_DIR="$T" timeout 60 "$SHELF" verify "$LAB" 2>&1); rc=$?
if [ "$rc" -eq 124 ]; then echo "The checks took too long. Wait a few seconds and click Check again." >&2; exit 1; fi
if [ "$rc" -ge 2 ]; then echo "$out" >&2; exit 1; fi
bad=0
for id in $CHECKS; do
  printf '%s\n' "$out" | grep -Eq "^(PASS|SKIP) $id " && continue
  bad=1; printf '%s\n' "$out" | grep -E -A2 "^FAIL $id "
done
[ "$bad" -eq 0 ] || echo "If you just applied a change, it may still be rolling out: wait a few seconds and click Check again." >&2
exit "$bad"
